/* Strict dotted-quad check: four 0-255 octets, no junk, no empty octet. */
bool validIpv4(const String& s) {
  if(s.length() < 7 || s.length() > 15) return false;
  if(s == "0.0.0.0" || s == "255.255.255.255") return false;
  int dots = 0, part = 0, digits = 0;
  for(int i=0; i<s.length(); i++) {
    char c = s[i];
    if(c == '.') {
      if(digits == 0 || part > 255) return false;
      dots++; part = 0; digits = 0;
    } else if(c >= '0' && c <= '9') {
      /* Reject leading zeros ("01") so the stored text is canonical. */
      if(digits == 0 && c == '0' && i+1 < s.length() && s[i+1] >= '0' && s[i+1] <= '9') return false;
      if(digits >= 3) return false;
      part = part * 10 + (c - '0');
      if(part > 255) return false;
      digits++;
    } else return false; }
  return dots == 3 && digits > 0;
}

/* Board IDs stay short and URL-safe: "Hero-" + letters/digits/-/_/. */
bool validBoardId(const String& id) {
  if(!id.startsWith("Hero-") || id.length() >= 24) return false;
  for(int i=0; i<id.length(); i++) {
    char c = id[i]; bool ok = (c>='A'&&c<='Z')||(c>='a'&&c<='z')||(c>='0'&&c<='9')||c=='-'||c=='_'||c=='.';
    if(!ok) return false;
  }
  return true;
}

