  int p = data.indexOf('|');
  if(p <= 0) return;
  wifiSsidNew = data.substring(0, p); wifiPassNew = data.substring(p+1); hasNewWifi = true;
}

void clearWifiCreds() {
  for(int i=WIFI_CREDS_ADDR; i<WIFI_CREDS_ADDR+100; i++) EEPROM.write(i, 0);
  EEPROM.commit(); hasNewWifi = false; wifiSsidNew = ""; wifiPassNew = "";
